-- كوكب كراكيب: PostgreSQL / Supabase starter schema
create extension if not exists "uuid-ossp";
create table profiles(id uuid primary key references auth.users on delete cascade, full_name text not null, phone text, avatar_url text, role text default 'user' check(role in('user','admin')), rating numeric(2,1) default 0, created_at timestamptz default now());
create table categories(id bigint generated by default as identity primary key, name_ar text unique not null, slug text unique not null, image_url text, active boolean default true);
create table products(id uuid primary key default uuid_generate_v4(), seller_id uuid references profiles not null, category_id bigint references categories, title text not null, description text, price numeric(12,2) check(price>=0), unit text not null, quantity numeric check(quantity>=0), condition text, latitude double precision, longitude double precision, delivery boolean default false, negotiable boolean default false, status text default 'pending' check(status in('pending','active','rejected','hidden','sold')), created_at timestamptz default now());
create table product_images(id bigint generated by default as identity primary key, product_id uuid references products on delete cascade, url text not null, is_primary boolean default false, sort_order int default 0);
create table favorites(user_id uuid references profiles, product_id uuid references products on delete cascade, primary key(user_id,product_id));
create table carts(id uuid primary key default uuid_generate_v4(), user_id uuid references profiles unique, updated_at timestamptz default now());
create table cart_items(cart_id uuid references carts on delete cascade, product_id uuid references products, quantity numeric check(quantity>0), primary key(cart_id,product_id));
create table addresses(id uuid primary key default uuid_generate_v4(), user_id uuid references profiles, label text, address text, governorate text, area text, latitude double precision, longitude double precision);
create table orders(id uuid primary key default uuid_generate_v4(), buyer_id uuid references profiles, address_id uuid references addresses, status text default 'review', subtotal numeric, delivery_fee numeric, total numeric, pickup_type text, payment_method text, created_at timestamptz default now());
create table order_items(id bigint generated by default as identity primary key, order_id uuid references orders on delete cascade, product_id uuid references products, seller_id uuid references profiles, quantity numeric, unit_price numeric);
create table conversations(id uuid primary key default uuid_generate_v4(), buyer_id uuid references profiles, seller_id uuid references profiles, product_id uuid references products, created_at timestamptz default now());
create table messages(id bigint generated by default as identity primary key, conversation_id uuid references conversations on delete cascade, sender_id uuid references profiles, body text, image_url text, location jsonb, read_at timestamptz, created_at timestamptz default now());
create table notifications(id bigint generated by default as identity primary key, user_id uuid references profiles, type text, title text, body text, data jsonb default '{}', read_at timestamptz, created_at timestamptz default now());
create table reviews(id bigint generated by default as identity primary key, order_id uuid unique references orders, reviewer_id uuid references profiles, seller_id uuid references profiles, rating int check(rating between 1 and 5), body text, created_at timestamptz default now());
create table reports(id bigint generated by default as identity primary key, reporter_id uuid references profiles, product_id uuid references products, reason text, status text default 'open', created_at timestamptz default now());
create table settings(key text primary key, value jsonb not null);
alter table profiles enable row level security; alter table products enable row level security; alter table favorites enable row level security; alter table orders enable row level security; alter table messages enable row level security;
create policy "Public active products" on products for select using(status='active' or seller_id=auth.uid());
create policy "Seller manages products" on products for all using(seller_id=auth.uid()) with check(seller_id=auth.uid());
create policy "Own profile" on profiles for update using(id=auth.uid()); create policy "Profiles readable" on profiles for select using(true);
create policy "Own favorites" on favorites for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "Own orders" on orders for select using(buyer_id=auth.uid());
create policy "Conversation messages" on messages for select using(exists(select 1 from conversations c where c.id=conversation_id and auth.uid() in(c.buyer_id,c.seller_id)));
